//! Slint UI: generated bindings plus one module per page.
//!
//! Every page module exposes `bind(&Rc<AppContext>)`, which installs the
//! callbacks of its Slint global. Work runs on tokio via
//! [`AppContext::spawn`] / [`AppContext::with_backend`]; results come back to
//! the UI thread through `slint::spawn_local`.

mod activation;
mod artwork;
mod cider_page;
mod context;
mod dialogs;
mod downloads;
mod format;
mod library;
mod library_add;
mod overview;
mod paged;
pub mod perf;
mod settings_page;
pub mod shot;

mod generated {
    // Generated by slint-build: uses `unsafe` internally and is not ours to lint.
    #![allow(unsafe_code, missing_docs, clippy::all, clippy::pedantic)]
    #![allow(clippy::unwrap_used, clippy::expect_used, clippy::todo)]
    slint::include_modules!();
}

use std::rc::Rc;

pub use activation::PendingActivation;
pub use context::{AppContext, UiEvent};
pub use generated::*;

/// Installs all UI callbacks and initial state.
pub fn bind(ctx: &Rc<AppContext>) {
    overview::bind(ctx);
    cider_page::bind(ctx);
    library::bind(ctx);
    library_add::bind(ctx);
    downloads::bind(ctx);
    settings_page::bind(ctx);
    dialogs::bind(ctx);
}
